static const size_t GENERIC_NUMERIC_NB_SUCCESSORS = 6;
static const Label GENERIC_NUMERIC_FEATURE_LABELS[] = {"nbElts", "variance", "eltWidth", "stddev", "cardinality", "cardinality_upper", "cardinality_lower", "skewness", "cardinality_ratio", "range_size", "cardinality_range_ratio", "mean", "kurtosis"};
static const size_t GENERIC_NUMERIC_NB_FEATURES = 13;


GBTModel  getGenericNumericGbtModel(FeatureGenerator featureGenerator)
{    GBTModel gbtModel = {
        .predictor        = &GENERIC_NUMERIC_PREDICTOR,
        .featureGenerator = featureGenerator,
        .nbSuccessors     = GENERIC_NUMERIC_NB_SUCCESSORS,
        .nbFeatures       = GENERIC_NUMERIC_NB_FEATURES,
        .featureLabels    = GENERIC_NUMERIC_FEATURE_LABELS,
    };
    return gbtModel;
}
